<template>
  <v-container fluid class="trr-root pa-0">
    <v-overlay :value="overlay">
      <v-progress-circular
        indeterminate
        color="primary"
        size="50"
      ></v-progress-circular>
    </v-overlay>

    <v-snackbar v-model="snackbar" :color="snackbarColor" :timeout="5000" top>
      {{ snackbarMessage }}
      <template v-slot:action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar = false">Close</v-btn>
      </template>
    </v-snackbar>

    <!-- ═══════════════════════════════════════════ HERO ══ -->
    <div class="tr-hero">
      <div class="tr-hero__left">
        <div class="tr-hero__icon">
          <v-icon color="white" size="22">mdi-account-multiple-check</v-icon>
        </div>
        <div>
          <div class="tr-hero__title">
            {{ isEditMode ? "Edit" : "Respond to" }} Training Recommendation
          </div>
          <div class="tr-hero__sub">
            {{
              isEditMode
                ? "Update your department's response to this training recommendation."
                : "Indicate your interest and provide participant details for this training recommendation."
            }}
          </div>
        </div>
      </div>
      <div class="tr-hero__stat" v-if="responseStatus">
        <v-chip :color="getStatusColor(responseStatus)" dark small>
          <v-icon left x-small>{{ getStatusIcon(responseStatus) }}</v-icon>
          {{ responseStatusDisplay }}
        </v-chip>
      </div>
    </div>

    <!-- ══════════════════════════════════ ACCESS DENIED ══ -->
    <v-container v-if="accessChecked && !isHOD" class="mt-8">
      <v-alert type="error" outlined prominent border="left">
        <v-row align="center">
          <v-col class="grow">
            <div class="font-weight-bold text-h6 mb-1">Access Restricted</div>
            <div>
              This module is only accessible to Heads of Department. Your
              account does not have the required HOD role.
            </div>
          </v-col>
          <v-col class="shrink">
            <v-icon size="48" color="error">mdi-lock-outline</v-icon>
          </v-col>
        </v-row>
      </v-alert>
    </v-container>

    <!-- ════════════════════════════════════ MAIN CONTENT ══ -->
    <v-container v-else-if="accessChecked && isHOD" fluid class="trr-main pa-4">
      <v-alert
        dense
        outlined
        type="error"
        v-if="error"
        transition="scale-transition"
      >
        <div class="d-flex align-center">
          <div class="flex-grow-1">{{ error }}</div>
          <v-btn icon small @click="error = null" class="ml-2">
            <v-icon small>mdi-close</v-icon>
          </v-btn>
        </div>
      </v-alert>

      <!-- Response Status Alert -->
      <v-row class="mt-4" v-if="!loading && responseId && responseStatus">
        <v-col cols="12">
          <v-alert :type="canEdit ? 'info' : 'warning'" prominent border="left">
            <v-row align="center">
              <v-col class="grow">
                <div class="font-weight-bold text-h6 mb-2">
                  <v-icon :color="canEdit ? 'info' : 'warning'" class="mr-2">
                    {{ canEdit ? "mdi-pencil" : "mdi-lock" }}
                  </v-icon>
                  {{ canEdit ? "Edit Mode" : "View Only" }}
                </div>
                <div class="body-2">
                  <strong>Current Status:</strong> {{ responseStatusDisplay }}
                </div>
                <div class="caption mt-1">
                  <span v-if="canEdit">
                    Your response is currently under HR review. You can still
                    make changes until it's approved or rejected.
                  </span>
                  <span v-else-if="responseStatus === 'approved'">
                    Your response has been approved. No further changes can be
                    made.
                  </span>
                  <span v-else-if="responseStatus === 'rejected'">
                    Your response has been rejected. Please contact HR for more
                    information.
                  </span>
                  <span v-else>
                    Your response has been submitted. No further changes can be
                    made.
                  </span>
                </div>
              </v-col>
              <v-col cols="auto">
                <v-chip :color="getStatusColor(responseStatus)" dark large>
                  <v-icon left small>
                    {{ getStatusIcon(responseStatus) }}
                  </v-icon>
                  {{ responseStatusDisplay }}
                </v-chip>
              </v-col>
            </v-row>
          </v-alert>
        </v-col>
      </v-row>

      <!-- Training Details -->
      <v-row class="mt-4" v-if="!loading">
        <v-col cols="12" lg="7">
          <v-card>
            <v-card-title class="indigo white--text">
              <v-icon left color="white">mdi-school-outline</v-icon>
              Training Details
            </v-card-title>
            <v-card-text class="pa-6">
              <div
                class="caption grey--text text--darken-2 font-weight-bold mb-1 text-uppercase"
              >
                Recommended Training
              </div>
              <h3 class="text-h5 mb-4 primary--text">{{ trainingTitle }}</h3>

              <v-row>
                <v-col cols="12" md="6">
                  <div class="info-label">
                    <v-icon small color="primary" class="mr-2"
                      >mdi-calendar-start</v-icon
                    >
                    START DATE
                  </div>
                  <div class="info-value">{{ formatDate(startDate) }}</div>
                </v-col>
                <v-col cols="12" md="6">
                  <div class="info-label">
                    <v-icon small color="primary" class="mr-2"
                      >mdi-calendar-end</v-icon
                    >
                    END DATE
                  </div>
                  <div class="info-value">{{ formatDate(endDate) }}</div>
                </v-col>
                <v-col cols="6">
                  <div class="info-label mb-2">
                    <v-icon small color="primary" class="mr-2">mdi-text</v-icon>
                    METHODOLOGY
                  </div>
                  <v-card outlined class="pa-3 grey lighten-5">
                    <p class="body-2 mb-0">{{ methodology }}</p>
                  </v-card>
                </v-col>
                <v-col cols="12" md="6">
                  <div class="info-label">
                    <v-icon small color="primary" class="mr-2"
                      >mdi-account-multiple</v-icon
                    >
                    MAX PARTICIPANTS
                  </div>
                  <div class="info-value">{{ maxParticipants }}</div>
                </v-col>
                <v-col cols="12" md="6">
                  <div class="info-label">
                    <v-icon small color="primary" class="mr-2"
                      >mdi-office-building-outline</v-icon
                    >
                    TRAINING INSTITUTION
                  </div>
                  <div class="info-value">{{ institution }}</div>
                </v-col>
                <v-col cols="12" md="6">
                  <div class="info-label">
                    <v-icon small color="primary" class="mr-2"
                      >mdi-map-marker</v-icon
                    >
                    LOCATION
                  </div>
                  <div class="info-value">{{ location }}</div>
                </v-col>
                <v-col cols="12" md="6" v-if="qualification">
                  <div class="info-label">
                    <v-icon small color="primary" class="mr-2"
                      >mdi-school-outline</v-icon
                    >
                    QUALIFICATION
                  </div>
                  <div class="info-value">{{ qualification }}</div>
                  <v-chip
                    v-if="qualificationLevel"
                    x-small
                    color="purple lighten-5"
                    text-color="purple darken-3"
                    class="mt-1"
                  >
                    {{ qualificationLevel }}
                  </v-chip>
                </v-col>
                <v-col cols="12" md="6" v-if="country">
                  <div class="info-label">
                    <v-icon small color="primary" class="mr-2"
                      >mdi-flag-outline</v-icon
                    >
                    COUNTRY
                  </div>
                  <div class="info-value">{{ country }}</div>
                </v-col>
                <v-divider class="my-4"></v-divider>
                <v-col
                  cols="12"
                  class="text-h6 font-weight-bold mb-3 primary--text"
                >
                  <v-icon color="primary" class="mr-2"
                    >mdi-account-check</v-icon
                  >
                  Eligibility Criteria
                </v-col>
                <v-col
                  cols="12"
                  sm="6"
                  md="4"
                  v-if="designations && designations.length > 0"
                >
                  <div
                    class="caption grey--text text--darken-2 mb-2 font-weight-bold"
                  >
                    TARGET DESIGNATIONS
                  </div>
                  <v-chip
                    v-for="(designation, index) in designations"
                    :key="'designation-' + index"
                    color="blue lighten-5"
                    text-color="blue darken-4"
                    small
                    class="mr-1 mb-1"
                  >
                    <v-icon small left>mdi-briefcase</v-icon>
                    <span class="font-weight-medium">{{
                      designation.name
                    }}</span>
                  </v-chip>
                </v-col>

                <!-- Age Criteria -->
                <v-col
                  cols="12"
                  sm="6"
                  md="4"
                  v-if="ageCriteria && ageCriteria.length > 0"
                >
                  <div
                    class="caption grey--text text--darken-2 mb-2 font-weight-bold"
                  >
                    AGE REQUIREMENTS
                  </div>
                  <v-chip
                    v-for="(ageCriterion, index) in ageCriteria"
                    :key="'age-' + index"
                    color="orange lighten-5"
                    text-color="orange darken-4"
                    small
                    class="mr-1 mb-1"
                  >
                    <v-icon small left>mdi-calendar-account</v-icon>
                    <span class="font-weight-medium">{{
                      formatAgeCriteria(ageCriterion)
                    }}</span>
                  </v-chip>
                </v-col>
                <v-col cols="12">
                  <div class="info-label mb-2">
                    <v-icon small color="primary" class="mr-2">mdi-text</v-icon>
                    DESCRIPTION
                  </div>
                  <v-card outlined class="pa-3 grey lighten-5">
                    <p class="body-2 mb-0">{{ description }}</p>
                  </v-card>
                </v-col>

                <!-- Facility Coverage ── only facilities in BOTH recommendation + HOD coverage -->
                <v-col cols="12" v-if="allowedFacilities.length">
                  <v-divider class="mb-4"></v-divider>
                  <v-alert
                    border="left"
                    colored-border
                    color="amber darken-2"
                    elevation="1"
                    class="mb-0"
                  >
                    <div class="d-flex align-center mb-2">
                      <v-icon color="amber darken-3" class="mr-2"
                        >mdi-hospital-building</v-icon
                      >
                      <span
                        class="subtitle-2 font-weight-bold amber--text text--darken-3 text-uppercase"
                      >
                        Applicable Facilities
                      </span>
                      <v-spacer />
                      <v-chip
                        x-small
                        color="amber lighten-4"
                        text-color="amber darken-4"
                        class="font-weight-bold"
                      >
                        {{ allowedFacilities.length }}
                        {{
                          allowedFacilities.length === 1
                            ? "facility"
                            : "facilities"
                        }}
                      </v-chip>
                    </div>
                    <div class="caption amber--text text--darken-2 mb-3">
                      Staff in the following facilities within your coverage are
                      eligible for this training
                    </div>
                    <div>
                      <v-chip
                        v-for="fac in showAllFacilities
                          ? allowedFacilities
                          : allowedFacilities.slice(0, 6)"
                        :key="fac.id"
                        small
                        color="amber lighten-4"
                        text-color="amber darken-4"
                        class="mr-1 mb-1 font-weight-medium"
                      >
                        <v-icon x-small left>mdi-map-marker</v-icon>
                        {{ fac.name || fac.id }}
                      </v-chip>
                      <v-btn
                        v-if="allowedFacilities.length > 6"
                        x-small
                        text
                        color="amber darken-3"
                        class="mb-1"
                        @click="showAllFacilities = !showAllFacilities"
                      >
                        <v-icon x-small left>
                          {{
                            showAllFacilities
                              ? "mdi-chevron-up"
                              : "mdi-chevron-down"
                          }}
                        </v-icon>
                        {{
                          showAllFacilities
                            ? "Show less"
                            : "Show " + (allowedFacilities.length - 6) + " more"
                        }}
                      </v-btn>
                    </div>
                  </v-alert>
                </v-col>

                <!-- No overlap warning -->
                <v-col cols="12" v-else-if="accessChecked && isHOD && !loading">
                  <v-divider class="mb-4"></v-divider>
                  <v-alert type="warning" outlined dense>
                    <v-icon small class="mr-1">mdi-alert</v-icon>
                    None of your covered facilities are included in this
                    training recommendation. You may not have staff eligible for
                    this training.
                  </v-alert>
                </v-col>
              </v-row>
            </v-card-text>
          </v-card>

          <!-- HR Review Section -->
          <v-card v-if="responseId && isEditMode" class="mt-4">
            <v-card-title class="orange darken-1 white--text">
              <v-icon left color="white">mdi-account-star</v-icon>
              HR Review
              <v-spacer></v-spacer>
              <v-chip
                v-if="!hrReview || !hrReview.status"
                color="white"
                text-color="orange darken-2"
                small
              >
                <v-icon small left>mdi-clock-outline</v-icon>
                Pending Review
              </v-chip>
            </v-card-title>
            <v-card-text class="pa-6">
              <!-- HR Review Exists -->
              <v-row v-if="hrReview && hrReview.status">
                <v-col cols="12" md="6">
                  <div class="info-label">
                    <v-icon small color="orange" class="mr-2"
                      >mdi-check-decagram</v-icon
                    >
                    DECISION
                  </div>
                  <v-chip
                    :color="getReviewStatusColor(hrReview.status.code)"
                    dark
                    class="mt-2"
                  >
                    <v-icon left small>
                      {{
                        hrReview.status.code === "approved"
                          ? "mdi-check-circle"
                          : "mdi-close-circle"
                      }}
                    </v-icon>
                    {{ hrReview.status.display }}
                  </v-chip>
                </v-col>
                <v-col cols="12" md="6">
                  <div class="info-label">
                    <v-icon small color="orange" class="mr-2"
                      >mdi-calendar</v-icon
                    >
                    REVIEW DATE
                  </div>
                  <div class="info-value">{{ formatDate(hrReview.date) }}</div>
                </v-col>
                <v-col cols="12" v-if="hrReview.reviewer">
                  <div class="info-label">
                    <v-icon small color="orange" class="mr-2"
                      >mdi-account</v-icon
                    >
                    REVIEWED BY
                  </div>
                  <div class="info-value">{{ hrReview.reviewer }}</div>
                </v-col>
                <v-col cols="12">
                  <div class="info-label mb-2">
                    <v-icon small color="orange" class="mr-2"
                      >mdi-comment-text</v-icon
                    >
                    HR COMMENTS
                  </div>
                  <v-card
                    outlined
                    class="pa-3"
                    :class="
                      hrReview.status.code === 'approved'
                        ? 'green lighten-5'
                        : 'red lighten-5'
                    "
                  >
                    <p class="body-2 mb-0 grey--text text--darken-3">
                      {{ hrReview.comments }}
                    </p>
                  </v-card>
                </v-col>
              </v-row>

              <!-- No HR Review Yet -->
              <v-row v-else>
                <v-col cols="12">
                  <v-alert type="info" outlined dense>
                    <div class="body-2">
                      <v-icon small class="mr-2">mdi-information</v-icon>
                      <strong>No HR review yet.</strong> Your response is
                      currently awaiting HR review.
                    </div>
                  </v-alert>
                </v-col>
              </v-row>
            </v-card-text>
          </v-card>
        </v-col>

        <!-- Response Form -->
        <v-col cols="12" lg="5">
          <v-card>
            <v-card-title class="success white--text">
              <v-icon left color="white">mdi-form-select</v-icon>
              Department Response
            </v-card-title>
            <v-card-text class="pa-6">
              <v-form ref="form" v-model="valid">
                <!-- STEP 1: Interest Question -->
                <v-card outlined class="mb-4">
                  <v-card-text>
                    <v-row>
                      <v-col cols="12">
                        <div class="font-weight-bold mb-3">
                          1. Is your department interested in this training? *
                        </div>
                        <v-radio-group
                          v-model="isInterested"
                          :rules="[
                            (v) => v !== null || 'Please select an option',
                          ]"
                          @change="onInterestChange"
                          :disabled="isReadOnly"
                        >
                          <v-radio
                            label="Yes, we are interested"
                            :value="true"
                            color="success"
                          ></v-radio>
                          <v-radio
                            label="No, not interested at this time"
                            :value="false"
                            color="error"
                          ></v-radio>
                        </v-radio-group>
                      </v-col>
                    </v-row>
                  </v-card-text>
                </v-card>

                <!-- STEP 2: Participants Selection (shown only if interested) -->
                <v-expand-transition>
                  <div v-if="isInterested">
                    <v-card outlined class="mb-4">
                      <v-card-title class="py-3">
                        <v-icon left color="primary"
                          >mdi-account-multiple</v-icon
                        >
                        2. Select Participants *
                        <v-spacer></v-spacer>
                        <v-chip
                          small
                          :color="participantsValid ? 'success' : 'warning'"
                        >
                          {{ selectedParticipants.length }} /
                          {{ maxParticipants }}
                        </v-chip>
                      </v-card-title>
                      <v-card-text>
                        <!-- Search and Items Per Page -->
                        <v-row dense class="mb-3">
                          <v-col cols="12" md="8">
                            <v-text-field
                              v-model="searchQuery"
                              prepend-inner-icon="mdi-magnify"
                              label="Search staff by name"
                              outlined
                              dense
                              clearable
                              @input="debouncedSearch"
                              :disabled="isReadOnly"
                            ></v-text-field>
                          </v-col>
                          <v-col cols="12" md="4">
                            <v-select
                              v-model="itemsPerPage"
                              :items="[10, 25, 50, 100]"
                              label="Items per page"
                              outlined
                              dense
                              @change="onItemsPerPageChange"
                              :disabled="isReadOnly"
                            ></v-select>
                          </v-col>
                        </v-row>

                        <!-- Criteria Filter Info -->
                        <v-alert
                          v-if="
                            designations.length > 0 ||
                              ageCriteria.length > 0 ||
                              qualificationCriteria.length > 0
                          "
                          type="info"
                          outlined
                          dense
                          class="mb-3"
                        >
                          <div class="caption">
                            <v-icon small class="mr-1">mdi-filter</v-icon>
                            <strong>Eligibility Filters Active:</strong> Showing
                            only staff matching required
                            <span v-if="designations.length > 0"
                              >designation(s)</span
                            ><span
                              v-if="
                                designations.length > 0 &&
                                  (ageCriteria.length > 0 ||
                                    qualificationCriteria.length > 0)
                              "
                              >, </span
                            ><span v-if="ageCriteria.length > 0"
                              >age criteria</span
                            ><span
                              v-if="
                                ageCriteria.length > 0 &&
                                  qualificationCriteria.length > 0
                              "
                              >, </span
                            ><span v-if="qualificationCriteria.length > 0"
                              >qualification level</span
                            >.
                          </div>
                          <!-- Qualification criteria detail chips -->
                          <div
                            v-if="qualificationCriteria.length > 0"
                            class="mt-1"
                          >
                            <v-chip
                              v-for="(q, i) in qualificationCriteria"
                              :key="i"
                              x-small
                              class="mr-1 mt-1"
                              :color="
                                q.condition === 'maximum'
                                  ? 'orange lighten-4'
                                  : 'blue lighten-4'
                              "
                              :text-color="
                                q.condition === 'maximum'
                                  ? 'orange darken-3'
                                  : 'blue darken-3'
                              "
                            >
                              <v-icon x-small left>
                                {{
                                  q.condition === "maximum"
                                    ? "mdi-arrow-collapse-up"
                                    : "mdi-arrow-up"
                                }}
                              </v-icon>
                              {{ q.condition === "maximum" ? "Max:" : "Min:" }}
                              {{ q.display || q.code }}
                            </v-chip>
                          </div>
                        </v-alert>

                        <!-- Loading Practitioners -->
                        <div
                          v-if="loadingPractitioners"
                          class="text-center py-4"
                        >
                          <v-progress-circular
                            indeterminate
                            color="primary"
                          ></v-progress-circular>
                          <p class="mt-2 caption">Loading staff members...</p>
                        </div>

                        <!-- Practitioners List -->
                        <div v-else>
                          <v-alert
                            v-if="practitioners.length === 0"
                            type="warning"
                            dense
                            outlined
                          >
                            <div class="font-weight-bold mb-1">
                              <v-icon small class="mr-1"
                                >mdi-account-off</v-icon
                              >
                              No eligible staff members found
                            </div>
                            <div class="caption">
                              <span
                                v-if="
                                  designations.length > 0 ||
                                    ageCriteria.length > 0 ||
                                    qualificationCriteria.length > 0
                                "
                              >
                                No staff match the required designation, age or
                                qualification criteria for this training.
                              </span>
                              <span v-else>
                                No active staff members found in your
                                department.
                              </span>
                            </div>
                          </v-alert>

                          <div v-else>
                            <!-- Practitioners Table/List -->
                            <div
                              style="max-height: 400px; overflow-y: auto;"
                              class="practitioners-list"
                            >
                              <v-list dense>
                                <v-list-item
                                  v-for="practitioner in practitioners"
                                  :key="practitioner.id"
                                  @click="
                                    !isReadOnly &&
                                      toggleParticipant(practitioner)
                                  "
                                  :disabled="
                                    isReadOnly ||
                                      !isParticipantSelectable(practitioner)
                                  "
                                >
                                  <v-list-item-action>
                                    <v-checkbox
                                      :input-value="
                                        isParticipantSelected(practitioner)
                                      "
                                      :disabled="
                                        isReadOnly ||
                                          !isParticipantSelectable(practitioner)
                                      "
                                      color="primary"
                                      @click.stop="
                                        !isReadOnly &&
                                          toggleParticipant(practitioner)
                                      "
                                    ></v-checkbox>
                                  </v-list-item-action>

                                  <v-list-item-content>
                                    <v-list-item-title>
                                      {{ practitioner.name }}
                                    </v-list-item-title>
                                    <v-list-item-subtitle>
                                      {{ practitioner.position }} -
                                      {{ practitioner.age }} Years
                                    </v-list-item-subtitle>
                                  </v-list-item-content>

                                  <v-list-item-icon
                                    v-if="isParticipantSelected(practitioner)"
                                  >
                                    <v-icon color="success"
                                      >mdi-check-circle</v-icon
                                    >
                                  </v-list-item-icon>
                                </v-list-item>
                              </v-list>
                            </div>

                            <!-- Pagination -->
                            <v-row class="mt-3" align="center">
                              <v-col cols="12" md="6">
                                <div class="caption grey--text">
                                  Showing
                                  {{ (currentPage - 1) * itemsPerPage + 1 }} -
                                  {{
                                    Math.min(
                                      currentPage * itemsPerPage,
                                      totalPractitioners,
                                    )
                                  }}
                                  of {{ totalPractitioners }} staff members
                                </div>
                              </v-col>
                              <v-col cols="12" md="6">
                                <v-pagination
                                  v-model="currentPage"
                                  :length="totalPages"
                                  :total-visible="7"
                                  @input="onPageChange"
                                  :disabled="isReadOnly"
                                ></v-pagination>
                              </v-col>
                            </v-row>

                            <!-- Validation Message -->
                            <v-alert
                              v-if="
                                selectedParticipants.length > maxParticipants
                              "
                              type="error"
                              dense
                              class="mt-3"
                            >
                              You have selected
                              {{ selectedParticipants.length }} participants,
                              but the maximum allowed is {{ maxParticipants }}.
                              Please deselect
                              {{
                                selectedParticipants.length - maxParticipants
                              }}
                              participant(s).
                            </v-alert>

                            <v-alert
                              v-else-if="
                                selectedParticipants.length > 0 &&
                                  selectedParticipants.length <= maxParticipants
                              "
                              type="success"
                              dense
                              class="mt-3"
                            >
                              {{ selectedParticipants.length }} participant(s)
                              selected
                            </v-alert>
                          </div>
                        </div>
                      </v-card-text>
                    </v-card>

                    <!-- STEP 3: Additional Comments -->
                  </div>
                </v-expand-transition>
                <v-card outlined>
                  <v-card-title class="py-3">
                    <v-icon left color="primary">mdi-comment-text</v-icon>
                    3. Additional Comments (Optional)
                  </v-card-title>
                  <v-card-text>
                    <v-textarea
                      v-model="comments"
                      outlined
                      rows="4"
                      placeholder="Enter any additional comments or special requirements..."
                      counter="500"
                      :rules="[
                        (v) =>
                          !v ||
                          v.length <= 500 ||
                          'Comments must be 500 characters or less',
                      ]"
                      :disabled="isReadOnly"
                    ></v-textarea>
                  </v-card-text>
                </v-card>
              </v-form>
            </v-card-text>

            <v-card-actions class="pa-6" v-if="!isReadOnly">
              <v-btn outlined @click="cancel">
                <v-icon left>mdi-close</v-icon>
                Cancel
              </v-btn>
              <v-spacer></v-spacer>
              <v-btn
                color="primary"
                :disabled="!canSubmit || submitting"
                :loading="submitting"
                @click="submit"
              >
                <v-icon left>mdi-send</v-icon>
                {{ isEditMode ? "Update Response" : "Submit Response" }}
              </v-btn>
            </v-card-actions>

            <v-card-actions class="pa-6" v-else>
              <v-btn outlined block @click="cancel">
                <v-icon left>mdi-arrow-left</v-icon>
                Back
              </v-btn>
            </v-card-actions>
          </v-card>
        </v-col>
      </v-row> </v-container
    ><!-- /trr-main -->

    <!-- ══════════════════════ INITIAL LOADING ══ -->
    <v-container v-else class="mt-8 text-center">
      <v-progress-circular indeterminate color="primary" size="64" />
      <div class="mt-4 grey--text text-body-1">Verifying access…</div>
    </v-container> </v-container
  ><!-- /trr-root -->
</template>

<script>
import processQuestionnaire from "../../mixins/processQuestionnaire";
import generalMixin from "../../mixins/general";
export default {
  name: "TrainingRecommendationResponse",
  props: ["queries"],
  mixins: [processQuestionnaire, generalMixin],
  data() {
    return {
      url:
        "http://ihris.org/fhir/Questionnaire/ihris-department-training-response",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/training-recommendation-response-profile",
      overlay: false,
      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      valid: false,
      submitting: false,
      loading: true,
      loadingPractitioners: false,

      // Edit mode
      isEditMode: false,
      isReadOnly: false,
      responseId: null,
      responseStatus: null,
      responseStatusDisplay: "",
      existingResponseData: null, // Store full existing response
      canEdit: false, // Track if editing is allowed
      accessChecked: false,
      isHOD: false,
      showAllFacilities: false,

      // HR Review data
      hrReview: null,

      // Form data
      isInterested: null,
      selectedParticipants: [],
      comments: "",
      searchQuery: "",
      searchDebounce: null,

      // Pagination
      currentPage: 1,
      prevPage: 0,
      itemsPerPage: 25,
      totalPractitioners: 0,
      practitioners: [],
      link: [],

      // Training details
      recommendationId: null,
      departmentCode: null,
      trainingTitle: "",
      startDate: "",
      endDate: "",
      location: "",
      institution: "",
      qualification: "",
      qualificationLevel: "",
      country: "",
      methodology: "",
      maxParticipants: 0,
      description: "",
      designations: [],
      ageCriteria: [],
      qualificationCriteria: [],
      recommendationFacilities: [],
      HODFacilities: [],
      error: "",
    };
  },

  computed: {
    allowedFacilities() {
      // Intersection: HOD-covered facilities that are also in the recommendation
      var recSet = new Set(this.recommendationFacilities);
      return this.HODFacilities.filter(function(f) {
        return recSet.has(f.id);
      });
    },

    totalPages() {
      return Math.ceil(this.totalPractitioners / this.itemsPerPage);
    },

    participantsValid() {
      return (
        this.selectedParticipants.length > 0 &&
        this.selectedParticipants.length <= this.maxParticipants
      );
    },

    canSubmit() {
      if (this.isInterested === null) return false;
      if (this.isInterested === false) return true;
      if (!this.participantsValid) return false;
      return this.valid;
    },
  },

  methods: {
    async checkAccess() {
      try {
        this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!this.loggedInStaff.practitioner) {
          this.accessChecked = true;
          return;
        }
        const practitionerId = this.loggedInStaff.practitioner;
        const resp = await fetch(
          `/site/general/getHOD/${this.loggedInStaff.practitioner}`,
        );
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const hodList = await resp.json();
        const matched = Array.isArray(hodList)
          ? hodList.find(function(h) {
              return h.practitioners.includes(practitionerId);
            })
          : null;
        if (!matched) {
          this.isHOD = false;
          this.accessChecked = true;
          return;
        }

        this.isHOD = true;

        // coverage is always a flat array of { id, name } facility objects
        const coverageArr = Array.isArray(matched.coverage)
          ? matched.coverage
          : [];
        this.HODFacilities = coverageArr.map(function(f) {
          return { id: f.id, name: f.name };
        });
      } catch (err) {
        console.error("checkAccess error:", err);
        this.showSnackbar("Failed to verify HR access.", "error");
        this.isHOD = false;
      } finally {
        this.accessChecked = true;
      }
    },
    async loadTrainingDetails() {
      try {
        if (!this.loggedInStaff.department.code) {
          this.$store.commit("setMessage", {
            type: "error",
            text: "We cant determine your department data",
          });
          return;
        }
        const response = await fetch(`/fhir/Basic/${this.recommendationId}`);
        const recommendation = await response.json();
        let needid = recommendation.extension
          .find(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/training-need-reference",
          )
          ?.valueReference?.reference?.split("/")?.[1];
        let need = await fetch("/fhir/Basic/" + needid);
        need = await need.json();
        this.recommendationFacilities = need.extension
          .filter(
            (ext) =>
              ext.url === "http://ihris.org/fhir/StructureDefinition/facility",
          )
          ?.map((rec) => rec.valueReference.reference.split("/")[1]);
        const titleExt = recommendation.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
        );
        this.trainingTitle = titleExt?.valueString || "";

        this.institution = recommendation.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/planning-institution",
        )?.valueString;

        const qualNameOther = recommendation.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/qualification-name-other",
        )?.valueString;
        const qualNameRef = recommendation.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/qualification-name",
        )?.valueReference?.display;
        this.qualification = qualNameOther || qualNameRef || "";

        this.qualificationLevel =
          recommendation.extension.find(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/qualification-level",
          )?.valueCoding?.display || "";

        this.country =
          recommendation.extension.find(
            (ext) =>
              ext.url === "http://ihris.org/fhir/StructureDefinition/country",
          )?.valueCoding?.display || "";

        const startExt = recommendation.extension.find(
          (ext) =>
            ext.url === "http://ihris.org/fhir/StructureDefinition/start-date",
        );
        this.startDate = startExt?.valueDate || "";

        const endExt = recommendation.extension.find(
          (ext) =>
            ext.url === "http://ihris.org/fhir/StructureDefinition/end-date",
        );
        this.endDate = endExt?.valueDate || "";

        const locExt = recommendation.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/training-location",
        );
        this.location = locExt?.valueString || "";

        this.methodology = recommendation.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/learning-methodology",
        )?.valueCoding?.display;

        //get max participant for this department
        let department = recommendation.extension.find((ext) => {
          return (
            ext.url ===
              "http://ihris.org/fhir/StructureDefinition/training-recommendation-department" &&
            ext.extension.find((ext) => {
              return (
                ext.url == "department" &&
                ext.valueCoding.code === this.loggedInStaff.department.code
              );
            })
          );
        });
        this.maxParticipants =
          department?.extension?.find((ext) => {
            return ext.url == "total-participants";
          })?.valueInteger || 0;

        const descExt = recommendation.extension.find(
          (ext) =>
            ext.url === "http://ihris.org/fhir/StructureDefinition/description",
        );
        this.description = descExt?.valueString || "";
        this.designations = recommendation.extension
          .filter(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/designation",
          )
          .map(
            (ext) =>
              ext.valueReference?.display || ext.valueReference?.reference,
          )
          .filter(Boolean);
        // Extract age criteria
        this.ageCriteria = recommendation.extension
          .filter(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/training-recommendation-age",
          )
          .map((ext) => {
            const ageExt = ext.extension || [];
            const typeExt = ageExt.find((e) => e.url === "condition");
            const valueExt = ageExt.find((e) => e.url === "exact");
            const minValueExt = ageExt.find((e) => e.url === "min");
            const maxValueExt = ageExt.find((e) => e.url === "max");

            if (typeExt) {
              const ageItem = {
                type: typeExt.valueString,
              };

              if (valueExt) {
                ageItem.value = valueExt.valueInteger;
              }
              if (minValueExt) {
                ageItem.minValue = minValueExt.valueInteger;
              }
              if (maxValueExt) {
                ageItem.maxValue = maxValueExt.valueInteger;
              }

              return ageItem;
            }
            return null;
          })
          .filter(Boolean);

        // Extract qualification criteria
        this.qualificationCriteria = recommendation.extension
          .filter(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/training-recommendation-qualification",
          )
          .map((ext) => {
            const q = ext.extension || [];
            // Sub-extension key is "qualification" per the FHIR resource structure
            const lvl = q.find((e) => e.url === "qualification")?.valueCoding;
            return {
              code: lvl?.code || null,
              system: lvl?.system || null,
              display: lvl?.display || lvl?.code || null,
              condition:
                q.find((e) => e.url === "condition")?.valueString || "atleast",
            };
          })
          .filter((q) => q.code);

        if (this.designations.length) {
          for (let index in this.designations) {
            let designation = this.designations[index];
            let desDet = await fetch("/fhir/" + designation);
            desDet = await desDet.json();
            let name = desDet.extension.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
              );
            })?.valueString;
            this.designations[index] = {
              name,
              id: designation,
            };
          }
        }
      } catch (error) {
        console.error("Error loading training details:", error);
        this.showSnackbar("Error loading training details", "error");
      }
    },

    async loadPractitioners(restart = false) {
      this.loadingPractitioners = true;
      let allowedlocations = this.HODFacilities.filter((hodfac) =>
        this.recommendationFacilities.find((recfac) => recfac == hodfac.id),
      )
        ?.map((rec) => rec.id)
        ?.join(",");

      try {
        let url = "";

        if (restart) {
          this.currentPage = 1;
        }

        // Build URL based on pagination
        if (this.currentPage > 1 && this.link.length > 0) {
          if (this.currentPage === this.prevPage - 1) {
            url =
              this.link.find((link) => link.relation === "previous")?.url || "";
          } else if (this.currentPage === this.prevPage + 1) {
            url = this.link.find((link) => link.relation === "next")?.url || "";
          }

          if (url) {
            url = url
              .replace(/_getpages=[^&]*&*/, "")
              .replace("/fhir?", "/fhir/PractitionerRole?");
            url = url.substring(url.indexOf("/fhir/"));

            if (url.indexOf("active=true") === -1) {
              url = url + "&active=true";
            }
            if (url.indexOf("_include=PractitionerRole:practitioner") === -1) {
              url = url + "&_include=PractitionerRole:practitioner";
            }
            if (url.indexOf("_include=PractitionerRole:roleposition") === -1) {
              url = url + "&_include=PractitionerRole:roleposition";
            }
            if (url.indexOf("_sort=-_lastUpdated") === -1) {
              url = url + "&_sort=-_lastUpdated";
            }
            if (url.indexOf("_total=accurate") === -1) {
              url = url + "&_total=accurate";
            }
            if (url.indexOf(`location=${allowedlocations}`) === -1) {
              url = url + `&location=${allowedlocations}`;
            }
          }
        }
        // Build initial URL
        if (url === "") {
          url = `/fhir/PractitionerRole?active=true&location=${allowedlocations}&_count=${this.itemsPerPage}&_include=PractitionerRole:practitioner&_include=PractitionerRole:roleposition&&_sort=-_lastUpdated&_total=accurate`;

          // Add search term if exists
          if (this.searchQuery) {
            url += `&practitioner.name:contains=${encodeURIComponent(
              this.searchQuery,
            )}`;
          }
        }

        this.prevPage = this.currentPage;

        const response = await fetch(url);
        const bundle = await response.json();

        if (bundle.total >= 0) {
          this.totalPractitioners = bundle.total;
          this.link = bundle.link || [];
        }

        if (bundle.entry) {
          const practitionerMap = new Map();
          const positionMap = new Map(); // Store position resources

          // Process practitioners
          bundle.entry.forEach((entry) => {
            if (entry.resource.resourceType === "Practitioner") {
              const practitioner = entry.resource;
              const name = practitioner.name?.[0];
              const fullName = name
                ? `${name.given?.join(" ") || ""} ${name.family || ""}`.trim()
                : "Unknown";

              // Calculate age from birthDate if available
              let age = null;
              if (practitioner.birthDate) {
                const birthDate = new Date(practitioner.birthDate);
                const today = new Date();
                age = today.getFullYear() - birthDate.getFullYear();
                const monthDiff = today.getMonth() - birthDate.getMonth();
                if (
                  monthDiff < 0 ||
                  (monthDiff === 0 && today.getDate() < birthDate.getDate())
                ) {
                  age--;
                }
              }

              practitionerMap.set(practitioner.id, {
                id: practitioner.id,
                name: fullName,
                position: "",
                reference: `Practitioner/${practitioner.id}`,
                age: age,
                designationId: null,
              });
            }
          });

          // Process position resources (Basic resources)
          bundle.entry.forEach((entry) => {
            if (entry.resource.resourceType === "Basic") {
              positionMap.set(entry.resource.id, entry.resource);
            }
          });

          // Add role and position information
          bundle.entry.forEach((entry) => {
            if (entry.resource.resourceType === "PractitionerRole") {
              const role = entry.resource;
              const practitionerId = role.practitioner?.reference?.split(
                "/",
              )[1];

              if (practitionerId && practitionerMap.has(practitionerId)) {
                const practitioner = practitionerMap.get(practitionerId);

                // Get position resource reference
                const positionRef = role.extension?.find(
                  (ext) =>
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/position-reference",
                )?.valueReference?.reference;

                if (positionRef) {
                  const positionId = positionRef.split("/")[1];
                  const positionResource = positionMap.get(positionId);
                  practitioner.position = positionResource.extension.find(
                    (ext) => {
                      return (
                        ext.url ===
                        "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
                      );
                    },
                  )?.valueString;

                  if (positionResource) {
                    // Extract designation
                    const designationExt = positionResource.extension?.find(
                      (ext) =>
                        ext.url ===
                        "http://ihris.org/fhir/StructureDefinition/designation",
                    );
                    if (designationExt?.valueReference?.reference) {
                      practitioner.designationId =
                        designationExt.valueReference.reference;
                    }

                    let department = positionResource.extension?.find(
                      (ext) =>
                        ext.url ===
                        "http://ihris.org/fhir/StructureDefinition/department",
                    )?.valueCoding?.code;
                    practitioner.department = department;
                  }
                }
              }
            }
          });

          // Filter practitioners based on recommendation criteria
          let filteredPractitioners = Array.from(
            practitionerMap.values(),
          ).filter((p) => p.name !== "Unknown");

          filteredPractitioners = filteredPractitioners.filter((p) => {
            return p.department === this.loggedInStaff?.department?.code;
          });

          // Apply designation filter
          if (this.designations && this.designations.length > 0) {
            filteredPractitioners = filteredPractitioners.filter((p) => {
              if (!p.designationId) return false;
              return this.designations.some((d) => d.id === p.designationId);
            });
          }

          // Apply age criteria filter
          if (this.ageCriteria && this.ageCriteria.length > 0) {
            filteredPractitioners = filteredPractitioners.filter((p) => {
              if (p.age === null) return false; // Exclude if age unknown

              // Check if practitioner meets ANY of the age criteria
              return this.ageCriteria.some((criteria) => {
                switch (criteria.type) {
                  case "greater-than":
                    return p.age > criteria.minValue;
                  case "less-than":
                    return p.age < criteria.maxValue;
                  case "range":
                    return (
                      p.age >= criteria.minValue && p.age <= criteria.maxValue
                    );
                  case "exact":
                    return p.age === criteria.value;
                  default:
                    return true;
                }
              });
            });
          }

          // Apply qualification criteria filter
          if (
            this.qualificationCriteria &&
            this.qualificationCriteria.length > 0
          ) {
            // For each criterion, query education history for matching practitioners.
            // A practitioner qualifies if they satisfy ANY one of the criteria (OR logic).
            const practitionerIds = filteredPractitioners.map(
              (p) => "Practitioner/" + p.id,
            );

            if (practitionerIds.length > 0) {
              const matchedIdSets = await Promise.all(
                this.qualificationCriteria.map(async (criterion) => {
                  try {
                    const params = new URLSearchParams({
                      _profile:
                        "http://ihris.org/fhir/StructureDefinition/education-history-profile",
                      practitioner: practitionerIds.join(","),
                      qualificationlevel: criterion.code,
                      _count: 1000,
                      _elements: "extension",
                    });
                    // For 'maximum' condition add ishighestqualification=yes so
                    // only records where this level is the highest will match.
                    if (criterion.condition === "maximum") {
                      params.set("ishighestqualification", "yes");
                    }
                    const res = await fetch(`/fhir/Basic?${params}`);
                    const bundle = await res.json();
                    const ids = new Set();
                    for (const entry of bundle.entry || []) {
                      const practExt = entry.resource.extension?.find(
                        (e) =>
                          e.url ===
                          "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
                      );
                      const ref = practExt?.valueReference?.reference;
                      if (ref) ids.add(ref.split("/")[1]);
                    }
                    return ids;
                  } catch (_) {
                    return new Set();
                  }
                }),
              );

              // Union all matched sets — a practitioner passes if they match ANY criterion
              const qualifiedIds = matchedIdSets.reduce(
                (union, set) => new Set([...union, ...set]),
                new Set(),
              );

              filteredPractitioners = filteredPractitioners.filter((p) =>
                qualifiedIds.has(p.id),
              );
            }
          }

          this.practitioners = filteredPractitioners.sort((a, b) =>
            a.name.localeCompare(b.name),
          );
        }
      } catch (error) {
        console.error("Error loading practitioners:", error);
        this.showSnackbar("Error loading staff members", "error");
      } finally {
        this.loadingPractitioners = false;
      }
    },

    async loadExistingResponse() {
      // First check if there's a responseId from query params (edit mode)
      if (!this.responseId) {
        // No responseId - check if current user has already responded
        await this.checkCurrentUserResponse();
        return;
      }

      // ResponseId exists - load that specific response
      try {
        const response = await fetch(`/fhir/Basic/${this.responseId}`);
        const responseData = await response.json();

        // Load response status
        const responseStatusExt = responseData.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/training-recommendation-response",
        );
        if (responseStatusExt) {
          this.responseStatus = responseStatusExt.valueCoding.code;
          this.responseStatusDisplay = responseStatusExt.valueCoding.display;
          this.isInterested = this.responseStatus === "interested";
        }

        // Check request status to determine if editing is allowed
        const statusExt = responseData.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/request-status",
        );

        let requestStatus = null;
        if (statusExt) {
          requestStatus = statusExt.valueCoding.code;

          // Allow editing only if status is underhrreview
          this.canEdit = requestStatus === "underhrreview";
          this.isReadOnly = !this.canEdit;
          this.isEditMode = true;
        } else {
          // No status - treat as editable
          this.canEdit = true;
          this.isReadOnly = false;
          this.isEditMode = true;
        }

        // Load participants
        const participantExts = responseData.extension.filter(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
        );

        if (participantExts.length > 0 && this.isInterested) {
          const participantReferences = participantExts.map(
            (ext) => ext.valueReference.reference,
          );

          // Load practitioners first
          await this.loadPractitioners(true);

          // Select matching participants
          this.selectedParticipants = this.practitioners.filter((p) =>
            participantReferences.includes(p.reference),
          );

          // Also mark any participants not on current page
          participantExts.forEach((ext) => {
            const ref = ext.valueReference.reference;
            const id = ref.split("/")[1];

            if (!this.selectedParticipants.find((p) => p.id === id)) {
              this.selectedParticipants.push({
                id: id,
                reference: ref,
                name: "Loading...",
                position: "",
              });
            }
          });
        }

        // Load comments
        const commentsExt = responseData.extension.find(
          (ext) =>
            ext.url === "http://ihris.org/fhir/StructureDefinition/comments",
        );
        if (commentsExt) {
          this.comments = commentsExt.valueString || "";
        }

        // Load HR review if exists
        await this.loadHRReview();
      } catch (error) {
        console.error("Error loading existing response:", error);
        this.showSnackbar("Error loading existing response", "error");
      }
    },

    async checkCurrentUserResponse() {
      try {
        const userId = this.$store.state.user?.obj?.resource?.id;
        if (!userId) {
          console.error("User ID not found");
          // Allow new response if user ID not found
          this.canEdit = true;
          this.isReadOnly = false;
          this.isEditMode = false;
          return;
        }

        // Build search URL to find current user's response
        const url = `/fhir/Basic?_profile=http://ihris.org/fhir/StructureDefinition/training-recommendation-response-profile&user=Person/${userId}&trainingrecommendation=Basic/${this.recommendationId}`;

        const response = await fetch(url);
        const bundle = await response.json();

        if (bundle.entry && bundle.entry.length > 0) {
          // Found existing response from this user
          const existingResponse = bundle.entry[0].resource;
          this.responseId = existingResponse.id;

          // Extract request status
          const statusExt = existingResponse.extension?.find(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/request-status",
          );

          let requestStatus = null;
          if (statusExt?.valueCoding) {
            requestStatus = statusExt.valueCoding.code;
            this.responseStatus = requestStatus;
            this.responseStatusDisplay =
              statusExt.valueCoding.display || requestStatus;
          }

          // Check if editing is allowed (only if status is underhrreview)
          this.canEdit = requestStatus === "underhrreview";
          this.isReadOnly = !this.canEdit;
          this.isEditMode = true;

          // Load the existing response data
          await this.loadExistingResponse();

          // Load HR review
          await this.loadHRReview();
        } else {
          // No existing response - allow new response
          this.canEdit = true;
          this.isReadOnly = false;
          this.isEditMode = false;
          this.responseId = null;
        }
      } catch (error) {
        console.error("Error checking current user response:", error);
        // On error, allow new response (fail open)
        this.canEdit = true;
        this.isReadOnly = false;
        this.isEditMode = false;
      }
    },

    async loadHRReview() {
      if (!this.responseId) return;

      try {
        const response = await fetch(
          `/fhir/Basic?_profile=http://ihris.org/fhir/StructureDefinition/hr-training-recommendation-review-profile&trainingrecommendationresponse=Basic/${this.responseId}`,
        );
        const bundle = await response.json();

        if (bundle.entry && bundle.entry.length > 0) {
          const review = bundle.entry[0].resource;

          const statusExt = review.extension.find(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/review-status",
          );

          const dateExt = review.extension.find(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/event-date",
          );

          const commentsExt = review.extension.find(
            (ext) =>
              ext.url === "http://ihris.org/fhir/StructureDefinition/comments",
          );

          const userExt = review.extension.find(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/user-reference",
          );

          this.hrReview = {
            status: statusExt?.valueCoding || null,
            date: dateExt?.valueDate || null,
            comments: commentsExt?.valueString || "",
            reviewer: null,
          };

          // Load reviewer name if available
          if (userExt?.valueReference?.reference) {
            const userId = userExt.valueReference.reference.split("/")[1];
            try {
              const userResponse = await fetch(`/fhir/Person/${userId}`);
              const user = await userResponse.json();
              const name = user.name?.[0];
              if (name) {
                this.hrReview.reviewer = `${name.given?.join(" ") ||
                  ""} ${name.family || ""}`.trim();
              }
            } catch (err) {
              console.error("Error loading reviewer:", err);
            }
          }
          let reviewId = review.id;
          let task = await fetch("/fhir/Basic?usertaskid=" + reviewId);
          let response = await task.json();
          if (response && response.entry && response.entry.length) {
            let taskDescr = response.entry[0].resource.extension.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/user-task-description"
              );
            });
            let statusIndex = taskDescr.extension.findIndex((ext) => {
              return ext.url === "status";
            });
            taskDescr.extension[statusIndex].valueCoding.code = "done";
            taskDescr.extension[statusIndex].valueCoding.display = "Done";

            fetch("/fhir/Basic/" + response.entry[0].resource.id, {
              method: "PUT",
              headers: {
                "Content-Type": "application/fhir+json",
                Accept: "application/fhir+json",
              },
              body: JSON.stringify(response.entry[0].resource),
            });
          }
        }
      } catch (error) {
        console.error("Error loading HR review:", error);
      }
    },
    formatAgeCriteria(ageItem) {
      if (!ageItem || !ageItem.type) return "";

      switch (ageItem.type) {
        case "greater-than":
          return `Age > ${ageItem.minValue}`;
        case "less-than":
          return `Age < ${ageItem.maxValue}`;
        case "range":
          return `Age ${ageItem.minValue}-${ageItem.maxValue}`;
        case "exact":
          return `Age = ${ageItem.value}`;
        default:
          return "";
      }
    },

    debouncedSearch() {
      clearTimeout(this.searchDebounce);
      this.searchDebounce = setTimeout(() => {
        this.loadPractitioners(true);
      }, 500);
    },

    onInterestChange() {
      this.selectedParticipants = [];
      if (this.isInterested === true && this.practitioners.length === 0) {
        this.loadPractitioners(true);
      }
    },

    onPageChange() {
      this.loadPractitioners(false);
    },

    onItemsPerPageChange() {
      this.loadPractitioners(true);
    },

    isParticipantSelected(practitioner) {
      return this.selectedParticipants.some((p) => p.id === practitioner.id);
    },

    isParticipantSelectable(practitioner) {
      const isAlreadySelected = this.isParticipantSelected(practitioner);
      const hasReachedMax =
        this.selectedParticipants.length >= this.maxParticipants;

      return isAlreadySelected || !hasReachedMax;
    },

    toggleParticipant(practitioner) {
      const index = this.selectedParticipants.findIndex(
        (p) => p.id === practitioner.id,
      );

      if (index > -1) {
        this.selectedParticipants.splice(index, 1);
      } else {
        if (this.selectedParticipants.length < this.maxParticipants) {
          this.selectedParticipants.push(practitioner);
        }
      }
    },

    async submit() {
      this.$refs.form.validate();
      if (!this.valid) return;
      this.submitting = true;
      this.overlay = true;
      this.error = "";
      if (this.isEditMode) {
        this.fhirId = this.responseId;
      }
      try {
        this.fhir = {
          interested: this.isInterested ? "interested" : "notinterested",
          comments: this.comments,
          participants: this.selectedParticipants.length
            ? this.selectedParticipants
            : [],
        };
        await this.processFHIR();
        this.showSnackbar("Response submitted successfully!", "success");
        this.clearForm();
        this.loading = true;
        await this.initAfterUserLoaded();
      } catch (error) {
        this.error = error;
      } finally {
        this.submitting = false;
        this.overlay = false;
      }
    },
    clearForm() {
      this.isInterested = null;
      this.selectedParticipants = [];
      this.comments = "";
      this.searchQuery = "";
      this.searchDebounce = null;
    },

    cancel() {
      this.$router.go(-1);
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },

    getStatusColor(status) {
      const colors = {
        interested: "success",
        notinterested: "grey",
        underreview: "orange",
        underhrreview: "orange",
        approved: "green",
        rejected: "red",
      };
      return colors[status] || "grey";
    },

    getStatusIcon(status) {
      const icons = {
        interested: "mdi-hand-okay",
        notinterested: "mdi-hand-back-left",
        underreview: "mdi-clock-outline",
        underhrreview: "mdi-clock-outline",
        approved: "mdi-check-circle",
        rejected: "mdi-close-circle",
      };
      return icons[status] || "mdi-help-circle";
    },

    getReviewStatusColor(status) {
      return status === "approved" ? "success" : "error";
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbar = true;
    },
    async initAfterUserLoaded() {
      this.recommendationId = this.queries?.recommendation;
      this.departmentCode = this.queries?.department;
      this.responseId = this.queries?.responseid;

      await this.checkAccess();
      if (!this.recommendationId || !this.isHOD) return;

      await this.loadTrainingDetails();

      if (this.responseId) {
        // ResponseId provided in query - load that specific response
        this.isEditMode = true;
        await this.loadExistingResponse();
      } else {
        // No responseId - check if current user has already responded
        await this.checkCurrentUserResponse();
      }

      this.loading = false;
    },
  },
  watch: {
    loadingUserData: {
      immediate: true,
      async handler(isLoading) {
        if (isLoading === false) {
          await this.initAfterUserLoaded();
        }
      },
    },
  },

  async created() {
    this.loading = true;
    await this.$nextTick();
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (v) => {
        if (!v) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        resolve();
      }, 15000);
    });

    if (!this.recommendationId) {
      this.showSnackbar("No recommendation ID provided", "error");
      this.loading = false;
      return;
    }
  },
};
</script>

